const now = new Date();
const currentSlot = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Seoul",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false
}).format(now);

const rows = items.map(i => i.json);

let filtered = rows.filter(r => {
  const slotValue = String(r.time_slot || r.scheduled_slot || "").trim().toLowerCase();
  const isTestRow = slotValue === "test";
  return (
    String(r.approval_status || r.status || "").trim().toLowerCase() === "approved" &&
    isTestRow &&
    String(r.deleted_at || "").trim() === "" &&
    String(r.publish_status || "").trim().toLowerCase() !== "posted"
  );
});

filtered = filtered.filter(r => {
  const platform = String(r.platform || r.content_type || "").trim().toLowerCase();
  if (!platform) return false;
  if (platform !== "reel") return true;

  const videoUrl = String(r.video_url || "").trim();
  const isTestRow = String(r.time_slot || r.scheduled_slot || "").trim().toLowerCase() === "test";
  if (isTestRow) {
    return /^https:\/\/.+\.mp4(\?|$)/i.test(videoUrl);
  }
  return videoUrl.startsWith("https://n8n.mykindredai.com/images/") && /\.mp4(\?|$)/i.test(videoUrl);
});

filtered = filtered.sort((a, b) => {
  const aTime = new Date(a.approved_at || a.updated_at || 0).getTime();
  const bTime = new Date(b.approved_at || b.updated_at || 0).getTime();
  if (bTime !== aTime) return bTime - aTime;
  return (Number(b.row_number) || 0) - (Number(a.row_number) || 0);
});

const seen = new Set();
const selected = [];
for (const r of filtered) {
  const key = String(r.content_key || r.content_id || "").trim();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  selected.push({
    ...r,
    current_slot: currentSlot,
    selected_at: new Date().toISOString(),
    test_mode: true
  });
}

return selected.map(r => ({ json: r }));

const row = $json;
const reelFallbackMp4 = 'https://www.w3schools.com/html/mov_bbb.mp4';
const rawVideoUrl =
  row.video_url ||
  row.reel_video_url ||
  row.preview_reel_url ||
  row.preview_video_url ||
  '';

const isTestRow = String(row.time_slot || row.scheduled_slot || '').trim().toLowerCase() === 'test';
const video_url = isTestRow
  ? reelFallbackMp4
  : rawVideoUrl;

return {
  json: {
    ...row,
    video_url,
    reel_publish_mode: video_url ? 'ready' : 'missing_video',
    captionText: `${row.final_title || ''}\n\n${row.body || ''}\n\n${row.hashtags || ''}`
  }
};

const row = $json;

return {
  json: {
    ...row,
    image_url: row.cover_url || '',
    captionText: `${row.final_title || ''}\n\n${row.body || ''}\n\n${row.hashtags || ''}`
  }
};

const created = $item(0).$node["Prepare Reel Publish"].json;

return {
  json: {
    ...created,
    post_id: $json.id,
    ig_post_id: $json.id,
    approval_status: 'posted',
    publish_status: 'posted',
    posted_at: new Date().toISOString()
  }
};

